package com.husarp.ankigo.shots

import android.view.View
import android.view.ViewGroup
import android.widget.FrameLayout
import com.husarp.ankigo.GameRepo
import com.husarp.ankigo.game.*
import com.husarp.ankigo.ui.*
import org.junit.After
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test

/** Generated by study answers, then consumed by the real battle panel's event player. */
class R40AStatusPlaybackTest {
    @get:Rule val paparazzi = Shots.rule()
    private var player: EventPlayer? = null
    @After fun clean() { player?.clear(); BattleShotKit.reset() }

    private fun play(g: Game, events: List<GameEvent>, expected: String, chip: String? = null, status: String? = null,
                     onPlayer: Boolean = true, animations: Boolean = true, reduced: Boolean = false) {
        paparazzi.unsafeUpdateConfig(deviceConfig = Shots.device(Size.PHONE, Theme.LIGHT))
        val ctx = Shots.files(paparazzi.context)
        FakeGame.withSprites = false; FakeGame.install(ctx)
        for ((name, value) in listOf("loadedData" to g.data, "held" to g.state)) {
            GameRepo::class.java.getDeclaredField(name).apply { isAccessible = true }.set(GameRepo, value)
        }
        GameRepo::class.java.getDeclaredMethod("rebuild").apply { isAccessible = true }.invoke(GameRepo)
        ctx.getSharedPreferences("study", 0).edit().putBoolean("reduceMotion", reduced).commit()
        AppPrefs.setAttackAnimations(ctx, animations)
        val panel = BattlePanelView(ctx)
        panel.renderAll(); panel.arena.setEnemyShown(true); panel.arena.moveOnScreen = { true }
        panel.arena.playerSprite.setPlaceholder("P", 0xFF5070B0.toInt())
        panel.arena.enemySprite.setPlaceholder("W", 0xFFB05050.toInt())
        val density = ctx.resources.displayMetrics.density
        panel.measure(View.MeasureSpec.makeMeasureSpec((412 * density).toInt(), View.MeasureSpec.EXACTLY),
            View.MeasureSpec.makeMeasureSpec((869 * density).toInt(), View.MeasureSpec.EXACTLY))
        panel.layout(0, 0, panel.measuredWidth, panel.measuredHeight)
        val floats = mutableListOf<FloatText>()
        panel.arena.setOnHierarchyChangeListener(object : ViewGroup.OnHierarchyChangeListener {
            override fun onChildViewAdded(parent: View?, child: View?) { if (child is FloatTextView) floats += child.ft }
            override fun onChildViewRemoved(parent: View?, child: View?) {}
        })
        val p = EventPlayer(panel, continueOnPanel = false); player = p
        p.enqueue(events)
        paparazzi.snapshot(FrameLayout(ctx).apply { addView(panel) }, "r40a-$expected-$animations-$reduced", 2000)
        repeat(3) { paparazzi.snapshot(FrameLayout(ctx), "r40a-flush", (it + 1) * 60_000L) }
        assertTrue("playback finished", p.idle)
        if (!reduced) assertTrue("$expected missing from $floats", floats.any { it.text == expected && it.onPlayer == onPlayer })
        if (status != null) assertEquals(status, if (onPlayer) panel.arena.playerStatus else panel.arena.enemyStatus)
        if (chip != null) assertTrue(chip, panel.arena.conditions.of(if (onPlayer) ConditionMarks.Slot.OURS else ConditionMarks.Slot.WILD).any { it.key == chip })
        val hp = panel.arena.javaClass.getDeclaredField(if (onPlayer) "pHpFrac" else "eHpFrac").apply { isAccessible = true }.getFloat(panel.arena)
        val actual = if (onPlayer) g.state.main!!.hp.toFloat() / StatCalc.maxHp(g.data, g.state.main!!)
            else g.state.battle!!.wild.hp.toFloat() / g.state.battle!!.maxWildHp(g.data)
        assertEquals("shown HP matches resolved status effects", actual, hp, .001f)
    }

    private fun status(key: String, word: String) {
        val g = R40AFlow.game(40)
        play(g, R40AFlow.apply(g, "apply$key"), word, status = key)
    }
    @Test fun burn() = status("brn", "Burned")
    @Test fun poison() = status("psn", "Poisoned")
    @Test fun toxic() = status("tox", "Badly poisoned")
    @Test fun paralysis() = status("par", "Paralyzed")
    @Test fun sleep() = status("slp", "Fell asleep")
    @Test fun freeze() = status("frz", "Frozen")

    private fun confusion(animations: Boolean = true, reduced: Boolean = false) {
        val pair = (0 until 32).map { seed ->
            val g = R40AFlow.game(seed)
            g.state.battle!!.player.volatiles["confusion"] = 3
            g to R40AFlow.round(g)
        }.first { (_, events) -> R40AFlow.effects(events).any { it.kind == EffectKind.CANT_MOVE && it.stat == "confusion" } }
        play(pair.first, pair.second, "Hurt itself", chip = "confusion", animations = animations, reduced = reduced)
    }
    @Test fun confusionSelfHit() = confusion()
    @Test fun confusionWithAttackAnimationsOff() = confusion(animations = false)
    @Test fun confusionWithReducedMotionRetainsHpAndCondition() = confusion(reduced = true)
    @Test fun infatuation() {
        val g = R40AFlow.game(40)
        play(g, R40AFlow.apply(g, "attract"), "In love", chip = "attract")
    }
    @Test fun flinch() {
        val g = R40AFlow.game(40)
        g.state.main!!.moves.apply { clear(); add("bite") }
        play(g, R40AFlow.round(g, 3, 2), "Flinched", onPlayer = false)
    }
    @Test fun leechSeed() {
        val g = R40AFlow.game(40)
        play(g, R40AFlow.apply(g, "leechseed"), "Seeded", chip = "leechseed")
    }
    @Test fun binding() {
        val g = R40AFlow.game(40)
        play(g, R40AFlow.apply(g, "wrap"), "Trapped", chip = "partiallytrapped")
    }
    private fun healing(item: String) {
        val g = R40AFlow.game(40, "splash"); g.state.main!!.hp = 1
        Economy.give(g.state, item); assertTrue(g.useItem(item, g.state.main!!.uid).ok)
        play(g, R40AFlow.round(g), Items.name(item), chip = if (item == "berry-juice") "heal.regen" else null)
    }
    @Test fun healingOverTime() = healing("berry-juice")
    @Test fun delayedHealing() = healing("sweet-heart")
}
